package com.mythic.localreview.format

import java.security.SecureRandom

/** Ids generated by this format (SPEC 3): 26-character ULIDs, which also match the id rule `[A-Za-z0-9_-]{1,64}`. */
object Ulid {
    private const val ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    private val random = SecureRandom()

    /** A new id: 48 bits of [now] in milliseconds, then 80 random bits, in Crockford base 32. */
    fun next(now: Long = System.currentTimeMillis()): String {
        val out = CharArray(26)
        var t = now
        for (i in 9 downTo 0) {
            out[i] = ALPHABET[(t and 31).toInt()]
            t = t ushr 5
        }
        val bytes = ByteArray(10).also(random::nextBytes)
        var bits = 0
        var acc = 0
        var pos = 10
        for (b in bytes) {
            acc = (acc shl 8) or (b.toInt() and 0xff)
            bits += 8
            while (bits >= 5) {
                out[pos++] = ALPHABET[(acc ushr (bits - 5)) and 31]
                bits -= 5
            }
            acc = acc and ((1 shl bits) - 1)
        }
        return String(out)
    }
}
